mapper.select:
select r.*, o.order_no, o.total_amount, m.nick_name as member_nick from mall_refund_request r left join mall_order o on o.order_id = r.order_id left join mall_member m on m.member_id = r.member_id
AND r.status = #{status} AND o.order_no like concat('%', #{orderNo}, '%') AND r.member_id = #{memberId}
order by r.create_time desc, r.request_id desc

mapper.update:
update mall_refund_request
set status = #{status},
    admin_remark = #{adminRemark},
    handle_by = #{handleBy},
    handle_time = #{handleTime}
where request_id = #{requestId}
